	private static StatementPattern pattern(String subject, IRI predicate, String object) {
		return new StatementPattern(Var.of(subject), constant("_p", predicate), Var.of(object));
	}

	private static Var constant(String name, IRI value) {
		return Var.of(name, value, true, true);
	}

	private static boolean storedNeutralPattern(PatternPlan pattern) {
		return pattern.readOnlyMask() == 0L && !pattern.namedContextScope && !pattern.contexts.isFixed()
				&& !pattern.c.hasSlot() && !pattern.c.isConstant() && pattern.statementOrder == null
				&& neutralTerm(pattern.s) && neutralTerm(pattern.p) && neutralTerm(pattern.o)
				&& neutralTerm(pattern.c);
	}

	private static boolean neutralTerm(Term term) {
		return !term.readOnly && !term.preserveExisting && !term.bindConstant;
	}

	private static Map<List<Long>, Long> drain(MultiJoinPlan plan, RowState row) throws Exception {
		Map<List<Long>, Long> bag = new LinkedHashMap<>();
		try (RowCursor cursor = plan.open(row)) {
			assertNotNull(cursor);
			while (cursor.next()) {
				List<Long> tuple = new ArrayList<>(row.slots.length);
				for (long id : row.slots) {
					tuple.add(id);
				}
				bag.merge(List.copyOf(tuple), 1L, Long::sum);
			}
		}
		return bag;
	}

	private static String order(SlotPlan[] order, NativeSlotLayout layout) {
		List<String> members = new ArrayList<>();
		for (SlotPlan child : order) {
			String roles = "";
			if (child instanceof PatternPlan pattern) {
				roles = ";roles=" + term(pattern.s) + "," + term(pattern.p) + "," + term(pattern.o)
						+ "," + term(pattern.c) + ";producedMask=" + pattern.producedMask()
						+ ";readOnlyMask=" + pattern.readOnlyMask() + ";namedScope=" + pattern.namedContextScope
						+ ";fixedContexts=" + pattern.contexts.isFixed();
			}
			members.add(quote(LmdbNativeExplain.describe(child, layout) + roles));
		}
		return "[" + String.join(",", members) + "]";
	}

	private static String term(Term term) {
		return "slot=" + term.slot + ":constant=" + term.constant + ":readOnly=" + term.readOnly
				+ ":bindConstant=" + term.bindConstant + ":preserveExisting=" + term.preserveExisting
				+ ":equalFields=" + term.equalFields;
	}

	private static String number(double value) {
		return Double.isFinite(value) ? Double.toString(value) : "null";
	}

	private static String quote(String value) {
		return "\"" + value.replace("\\", "\\\\").replace("\"", "\\\"")
				.replace("\n", "\\n").replace("\r", "\\r").replace("\t", "\\t") + "\"";
	}
